changes = 0
for i in 0 .. n - 2: if numbers[i] > numbers[i + 1]:
  changes += 1; if changes > 1: return false
  if i == 0 or numbers[i - 1] <= numbers[i + 1]: numbers[i] = numbers[i + 1]   (lower the left one)
  else: numbers[i + 1] = numbers[i]                                         (raise the right one)
return true
